-- Slow on purpose: this looks the row up again for every row.
-- Run it once to see how long it takes, then rewrite it.
ALTER TABLE data ADD COLUMN total REAL;
UPDATE data SET total = (SELECT d.qty * d.unit_price * (1 - d.discount) FROM data d WHERE d.order_id + 0 = data.order_id + 0);
